mapper.select:
SELECT JSON_UNQUOTE(JSON_EXTRACT(v.content_json,'$.responsibility')) AS responsibility
FROM preparation_version v JOIN preparation_item i ON i.owner_id=v.owner_id AND i.id=v.item_id AND i.kind='FACT'
WHERE v.owner_id=#{owner} AND v.item_id=#{id} AND v.id=#{versionId}

choose.when:
SELECT f.owner_id,f.session_id,f.question_id,f.answer_id
FROM review_feedback f JOIN review_feedback_revision r
  ON r.owner_id=f.owner_id AND r.feedback_id=f.id AND r.revision=#{ref.revision}
WHERE f.owner_id=#{owner} AND f.id=#{ref.id}
